// Steers the player's slide: starts it when a dash ends near a wall, then aims its velocity.
void update_hero_planar_distance_spring_motion(void) {
    struct Hero *q = (struct Hero *)g_hero;
    struct Hero *p;
    struct Hero *r;
    float t0;
    float d;
    float lim;
    float ang;
    int s;

    if (q->wall_hit != 0 && q->ground_distance > 0.0f && q->motion.speed_xy < g_frame_time * 3.0f &&
        FastVecLength(&q->motion.velocity) < g_frame_time * 3.0f && q->stick_magnitude < 0.2f) {
        s = q->state.control_mode;
        if (s == 0 || s == 2 || s == 4 || s == 10 || s == 1) {
            s = scale_ticks(5);
            r = (struct Hero *)g_hero;
            r->unk1EA = s;
        }
    }
    p = (struct Hero *)g_hero;
    if (p->unk1EA != 0) {
        d = vec_distance_xy(&p->motion.pos, &p->wall_contact_point);
        lim = p->capsule_radius * 0.9f;
        if (d < lim) {
            ang = fast_atan2(p->motion.pos.f[0] - p->wall_contact_point.f[0],
                             p->motion.pos.f[1] - p->wall_contact_point.f[1]);
            if (d < p->capsule_radius * 0.05f) {
                ang = p->motion.rot.f[2];
            }
            t0 = d - lim;
            Spring(&t0, (float *)&p->unk244, 0.0f, g_frame_scale_sq * 0.03f, g_frame_scale_sq * 0.3f,
                   g_frame_time * 2.8f);
            p->motion.platform_delta.f[0] = FastCos(ang) * p->unk244.f;
            p->motion.platform_delta.f[1] = FastSin(ang) * p->unk244.f;
            p->motion.platform_delta.f[2] = 0.0f;
        }
    } else {
        p->unk244.i = 0;
    }
}

extern int stick_direction_vs_facing(void);
/* Returns a tick count for the stick tilt. */
int get_hero_high_jump_input_window_frames(void) {
    int r = scale_ticks(12);
    int t = stick_direction_vs_facing();
    if (t == 2) {
        r = 0;
    } else if (t == 3) {
        r = scale_ticks(12);
    }
    return r;
}
extern void stick_target_v(int, float) __asm__("func_L00_00211F80");

// Classifies the stick direction into one of four quadrants (2, 3, 1 or 0).
int stick_direction_vs_facing(void) {
    struct Hero *p;
    float a;
    int r = 2;
    stick_target_v(0, 1.0f);
    p = (struct Hero *)g_hero;
    a = FastSubRots(p->motion.move_yaw, p->motion.rot.f[2]);
    if (FastDiffRots(a, 3.14159274f) < 0.785398185f) {
        r = 3;
    } else if (FastDiffRots(a, -1.57079637f) < 0.785398185f) {
        r = 1;
    } else if (FastDiffRots(a, 1.57079637f) < 0.785398185f) {
        r = 0;
    }
    return r;
}
